// WASM module loader for nodebox-electron.
// Initializes eagerly on import. Call functions only after isWasmReady() returns true.

// @ts-expect-error WASM module generated by wasm-pack
import init, { text_to_path, evaluate_library, get_node_templates, create_node } from '@wasm/nodebox_electron.js';

import type { Node } from '../types/node';

export interface NodeTemplate {
  name: string;
  prototype: string;
  category: string;
  description: string;
}

let ready = false;
let readyCallbacks: (() => void)[] = [];

init().then(() => {
  ready = true;
  for (const cb of readyCallbacks) cb();
  readyCallbacks = [];
});

export function isWasmReady(): boolean {
  return ready;
}

export function onWasmReady(cb: () => void): void {
  if (ready) cb();
  else readyCallbacks.push(cb);
}

export function textToPathSync(
  text: string,
  fontSize: number,
  positionX: number,
  positionY: number,
): string {
  return text_to_path(text, fontSize, positionX, positionY);
}

export function evaluateLibrary(libraryJson: string, frame: number): string {
  return evaluate_library(libraryJson, frame);
}

let cachedTemplates: NodeTemplate[] | null = null;

export function getNodeTemplates(): NodeTemplate[] {
  if (cachedTemplates) return cachedTemplates;
  const json = get_node_templates();
  cachedTemplates = JSON.parse(json) as NodeTemplate[];
  return cachedTemplates;
}

export function createNodeFromTemplate(
  templateName: string,
  libraryJson: string,
  x: number,
  y: number,
): Node {
  const json = create_node(templateName, libraryJson, x, y);
  return JSON.parse(json) as Node;
}
